دالة شفرة_قيصر(نص، ن) {
    متغير نص_مُشفر = ""
    من_أجل (حرف في نص) {
        متغير م = عدد(حرف)
        إذا (م >= عدد('a') و م <= عدد('z')) {
            م = م - عدد('a')
            م = (م + ن) % ٢٦
            م = م + عدد('a')
        }
        نص_مُشفر = نص_مُشفر + نص(م)
    }
    ارجع نص_مُشفر
}
```

